                { // path 2 (0, 1, 1)
                    const float g0 = __ldcs(dm1_1 + (int64_t)stage_r * 1152 + 0 + ch);
                    const float g1 = __ldcs(dm1_1 + (int64_t)stage_r * 1152 + 384 + ch);
                    const float g2 = __ldcs(dm1_1 + (int64_t)stage_r * 1152 + 768 + ch);
                    s_q[ch * 44 + 2] = 1.73205081f * g0;
                    s_q[ch * 44 + 5] = 1.73205081f * g1;
                    s_q[ch * 44 + 8] = 1.73205081f * g2;
