                    const float g1 = __ldcs(dm1_2 + (int64_t)stage_r * 1920 + 384 + ch);
                    const float g2 = __ldcs(dm1_2 + (int64_t)stage_r * 1920 + 768 + ch);
                    const float g3 = __ldcs(dm1_2 + (int64_t)stage_r * 1920 + 1152 + ch);
