                    s_q[ch * 44 + 14] = 1.93649167f * g1;
                    s_q[ch * 44 + 17] = 1.93649167f * g0;
                    s_q[ch * 44 + 20] = 2.23606798f * g2;
                    s_q[ch * 44 + 23] = 1.93649167f * g3;
                }
                { // path 6 (1, 1, 2)
