                    const float g1 = __ldcs(dm1_2 + (int64_t)stage_r * 1920 + 512 + ch);
                    const float g2 = __ldcs(dm1_2 + (int64_t)stage_r * 1920 + 896 + ch);
                    const float g3 = __ldcs(dm1_2 + (int64_t)stage_r * 1920 + 1280 + ch);
                    const float g4 = __ldcs(dm1_2 + (int64_t)stage_r * 1920 + 1664 + ch);
                    s_q[ch * 44 + 12] = -0.353553391f * g2 + -0.612372436f * g4;
                    s_q[ch * 44 + 15] = 0.612372436f * g1;
                    s_q[ch * 44 + 18] = 0.612372436f * g0;
                    s_q[ch * 44 + 21] = 0.707106781f * g2;
                    s_q[ch * 44 + 24] = 0.612372436f * g3;
                }
                { // path 7 (1, 3, 2)
                    const float g0 = __ldcs(dm1_2 + (int64_t)stage_r * 1920 + 256 + ch);
                    const float g1 = __ldcs(dm1_2 + (int64_t)stage_r * 1920 + 640 + ch);
                    const float g2 = __ldcs(dm1_2 + (int64_t)stage_r * 1920 + 1024 + ch);
                    const float g3 = __ldcs(dm1_2 + (int64_t)stage_r * 1920 + 1408 + ch);
                    const float g4 = __ldcs(dm1_2 + (int64_t)stage_r * 1920 + 1792 + ch);
                    s_q[ch * 44 + 13] = -1.44337567f * g2 + -2.5f * g4;
                    s_q[ch * 44 + 16] = 2.5f * g1;
                    s_q[ch * 44 + 19] = 2.5f * g0;
                    s_q[ch * 44 + 22] = 2.88675135f * g2;
                    s_q[ch * 44 + 25] = 2.5f * g3;
