                { // path 8 (0, 3, 3)
                    const float g0 = __ldcs(dm1_3 + (int64_t)stage_r * 1792 + 0 + ch);
                    const float g1 = __ldcs(dm1_3 + (int64_t)stage_r * 1792 + 256 + ch);
                    const float g2 = __ldcs(dm1_3 + (int64_t)stage_r * 1792 + 512 + ch);
                    const float g3 = __ldcs(dm1_3 + (int64_t)stage_r * 1792 + 768 + ch);
                    const float g4 = __ldcs(dm1_3 + (int64_t)stage_r * 1792 + 1024 + ch);
                    const float g5 = __ldcs(dm1_3 + (int64_t)stage_r * 1792 + 1280 + ch);
                    const float g6 = __ldcs(dm1_3 + (int64_t)stage_r * 1792 + 1536 + ch);
                    s_q[ch * 44 + 26] = -2.09165007f * g0 + -1.62018517f * g2;
                    s_q[ch * 44 + 28] = -1.32287566f * g3 + -1.70782513f * g5;
                    s_q[ch * 44 + 30] = -0.540061725f * g4 + -2.09165007f * g6;
                    s_q[ch * 44 + 32] = 2.1602469f * g2;
                    s_q[ch * 44 + 34] = 1.70782513f * g1;
                    s_q[ch * 44 + 36] = 2.64575131f * g3;
                    s_q[ch * 44 + 38] = 2.1602469f * g4;
                }
                { // path 9 (1, 2, 3)
                    const float g0 = __ldcs(dm1_3 + (int64_t)stage_r * 1792 + 128 + ch);
                    const float g1 = __ldcs(dm1_3 + (int64_t)stage_r * 1792 + 384 + ch);
                    const float g2 = __ldcs(dm1_3 + (int64_t)stage_r * 1792 + 640 + ch);
                    const float g3 = __ldcs(dm1_3 + (int64_t)stage_r * 1792 + 896 + ch);
                    const float g4 = __ldcs(dm1_3 + (int64_t)stage_r * 1792 + 1152 + ch);
                    const float g5 = __ldcs(dm1_3 + (int64_t)stage_r * 1792 + 1408 + ch);
                    const float g6 = __ldcs(dm1_3 + (int64_t)stage_r * 1792 + 1664 + ch);
                    s_q[ch * 44 + 27] = -0.456435465f * g0 + -0.353553391f * g2;
                    s_q[ch * 44 + 29] = -0.288675135f * g3 + -0.372677996f * g5;
                    s_q[ch * 44 + 31] = -0.11785113f * g4 + -0.456435465f * g6;
                    s_q[ch * 44 + 33] = 0.471404521f * g2;
                    s_q[ch * 44 + 35] = 0.372677996f * g1;
                    s_q[ch * 44 + 37] = 0.577350269f * g3;
