                    const float radial_dt = fmaf(ds3, r3, fmaf(ds2, r2, fmaf(ndt_hb, eb_f, r1)));  // 2^8 x d(w)/dt
                    const float q0 = Q0.z;
                    const float q1 = Q1.y;
                    const float q2 = Q2.x;
                    const float h = q0 * nx + q1 * ny + q2 * nz;
                    const float wx = w * x0_v;
                    pull_Gx = fmaf(wx, q0, pull_Gx);
                    pull_Gy = fmaf(wx, q1, pull_Gy);
                    pull_Gz = fmaf(wx, q2, pull_Gz);
                    dx0_acc = fmaf(w, h, dx0_acc);
                    pull_R = fmaf(radial_dt, x0_v * h, pull_R);
                }
                { // path 3 (1, 0, 1) raise
                    const uint2 c = __ldg(slab_ptr + 384 + channel);
                    const unsigned eb0 = (c.y & 0x0F800000u) + bias_shift;
                    const float eb_f = __uint_as_float(eb0);
                    const float r0 = __uint_as_float((c.x & 0x7FFFF8u) | eb0);
                    const float r1 = __uint_as_float((c.y & 0x7FFFF0u) | eb0);
                    const float r2 = __uint_as_float((__funnelshift_l(c.x, c.x, 20) & 0x7FF800u) | eb0);
                    const float r3 = __uint_as_float((__funnelshift_l(c.y, c.y, 19) & 0x7F8000u) | eb0);
                    const float w = fmaf(s3, r3, fmaf(s2, r2, fmaf(s1, r1, fmaf(nw_hb, eb_f, r0))));
                    const float radial_dt = fmaf(ds3, r3, fmaf(ds2, r2, fmaf(ndt_hb, eb_f, r1)));  // 2^8 x d(w)/dt
                    const float q0 = Q0.w;
                    const float q1 = Q1.z;
                    const float q2 = Q2.y;
                    const float h = q0 * nx + q1 * ny + q2 * nz;
                    pull_R = fmaf(radial_dt, xx * q0 + xy * q1 + xz * q2, pull_R);
                    dx1x_acc = fmaf(w, q0, dx1x_acc);
                    dx1y_acc = fmaf(w, q1, dx1y_acc);
                    dx1z_acc = fmaf(w, q2, dx1z_acc);
                }
                { // path 4 (1, 2, 1) lower
                    const uint2 c = __ldg(slab_ptr + 512 + channel);
                    const unsigned eb0 = (c.y & 0x0F800000u) + bias_shift;
                    const float eb_f = __uint_as_float(eb0);
                    const float r0 = __uint_as_float((c.x & 0x7FFFF8u) | eb0);
                    const float r1 = __uint_as_float((c.y & 0x7FFFF0u) | eb0);
                    const float r2 = __uint_as_float((__funnelshift_l(c.x, c.x, 20) & 0x7FF800u) | eb0);
                    const float r3 = __uint_as_float((__funnelshift_l(c.y, c.y, 19) & 0x7F8000u) | eb0);
                    const float w = fmaf(s3, r3, fmaf(s2, r2, fmaf(s1, r1, fmaf(nw_hb, eb_f, r0))));
                    const float radial_dt = fmaf(ds3, r3, fmaf(ds2, r2, fmaf(ndt_hb, eb_f, r1)));  // 2^8 x d(w)/dt
                    const float q0 = Q1.x;
                    const float q1 = Q1.w;
                    const float q2 = Q2.z;
                    const float h = q0 * nx + q1 * ny + q2 * nz;
                    const float A = xx * nx + xy * ny + xz * nz;
                    const float B = xx * q0 + xy * q1 + xz * q2;
                    pull_R = fmaf(radial_dt, A * h - 0.333333333f * B, pull_R);
                    const float wh = w * h, wA = w * A, wk = w * 0.333333333f;
                    pull_Gx = fmaf(wh, xx, fmaf(wA, q0, pull_Gx));
                    pull_Gy = fmaf(wh, xy, fmaf(wA, q1, pull_Gy));
                    pull_Gz = fmaf(wh, xz, fmaf(wA, q2, pull_Gz));
                    dx1x_acc = fmaf(wh, nx, fmaf(-wk, q0, dx1x_acc));
                    dx1y_acc = fmaf(wh, ny, fmaf(-wk, q1, dx1y_acc));
                    dx1z_acc = fmaf(wh, nz, fmaf(-wk, q2, dx1z_acc));
                }
            const float4 Q3 = sq4[3];
            const float4 Q4 = sq4[4];
            const float4 Q5 = sq4[5];
                { // path 5 (0, 2, 2) scalar
                    const uint2 c = __ldg(slab_ptr + 640 + channel);
                    const unsigned eb0 = (c.y & 0x0F800000u) + bias_shift;
                    const float eb_f = __uint_as_float(eb0);
                    const float r0 = __uint_as_float((c.x & 0x7FFFF8u) | eb0);
                    const float r1 = __uint_as_float((c.y & 0x7FFFF0u) | eb0);
                    const float r2 = __uint_as_float((__funnelshift_l(c.x, c.x, 20) & 0x7FF800u) | eb0);
                    const float r3 = __uint_as_float((__funnelshift_l(c.y, c.y, 19) & 0x7F8000u) | eb0);
                    const float w = fmaf(s3, r3, fmaf(s2, r2, fmaf(s1, r1, fmaf(nw_hb, eb_f, r0))));
                    const float radial_dt = fmaf(ds3, r3, fmaf(ds2, r2, fmaf(ndt_hb, eb_f, r1)));  // 2^8 x d(w)/dt
                    const float q0 = Q2.w;
                    const float q1 = Q3.z;
                    const float q2 = Q4.y;
                    const float q3 = Q5.x;
                    const float q4 = Q5.w;
                    const float qzz = -q0 - q3;
                    const float vx = q0 * nx + q1 * ny + q2 * nz, vy = q1 * nx + q3 * ny + q4 * nz, vz = q2 * nx + q4 * ny + qzz * nz;
                    const float h = nx * vx + ny * vy + nz * vz;
                    const float wx = 2.0f * w * x0_v;
                    pull_Gx = fmaf(wx, vx, pull_Gx);
                    pull_Gy = fmaf(wx, vy, pull_Gy);
                    pull_Gz = fmaf(wx, vz, pull_Gz);
                    dx0_acc = fmaf(w, h, dx0_acc);
                    pull_R = fmaf(radial_dt, x0_v * h, pull_R);
                }
            const float4 Q6 = sq4[6];
                { // path 6 (1, 1, 2) raise
                    const uint2 c = __ldg(slab_ptr + 768 + channel);
                    const unsigned eb0 = (c.y & 0x0F800000u) + bias_shift;
                    const float eb_f = __uint_as_float(eb0);
                    const float r0 = __uint_as_float((c.x & 0x7FFFF8u) | eb0);
                    const float r1 = __uint_as_float((c.y & 0x7FFFF0u) | eb0);
                    const float r2 = __uint_as_float((__funnelshift_l(c.x, c.x, 20) & 0x7FF800u) | eb0);
                    const float r3 = __uint_as_float((__funnelshift_l(c.y, c.y, 19) & 0x7F8000u) | eb0);
                    const float w = fmaf(s3, r3, fmaf(s2, r2, fmaf(s1, r1, fmaf(nw_hb, eb_f, r0))));
                    const float radial_dt = fmaf(ds3, r3, fmaf(ds2, r2, fmaf(ndt_hb, eb_f, r1)));  // 2^8 x d(w)/dt
                    const float q0 = Q3.x;
                    const float q1 = Q3.w;
                    const float q2 = Q4.z;
                    const float q3 = Q5.y;
                    const float q4 = Q6.x;
                    const float qzz = -q0 - q3;
                    const float vx = q0 * nx + q1 * ny + q2 * nz, vy = q1 * nx + q3 * ny + q4 * nz, vz = q2 * nx + q4 * ny + qzz * nz;
                    const float h = nx * vx + ny * vy + nz * vz;
                    pull_R = fmaf(radial_dt, 2.0f * (xx * vx + xy * vy + xz * vz), pull_R);
                    const float w2 = 2.0f * w;
                    dx1x_acc = fmaf(w2, vx, dx1x_acc);
                    dx1y_acc = fmaf(w2, vy, dx1y_acc);
                    dx1z_acc = fmaf(w2, vz, dx1z_acc);
                    pull_Gx = fmaf(w2, q0 * xx + q1 * xy + q2 * xz, pull_Gx);
                    pull_Gy = fmaf(w2, q1 * xx + q3 * xy + q4 * xz, pull_Gy);
                    pull_Gz = fmaf(w2, q2 * xx + q4 * xy + qzz * xz, pull_Gz);
                }
                { // path 7 (1, 3, 2) lower
                    const uint2 c = __ldg(slab_ptr + 896 + channel);
                    const unsigned eb0 = (c.y & 0x0F800000u) + bias_shift;
                    const float eb_f = __uint_as_float(eb0);
                    const float r0 = __uint_as_float((c.x & 0x7FFFF8u) | eb0);
                    const float r1 = __uint_as_float((c.y & 0x7FFFF0u) | eb0);
                    const float r2 = __uint_as_float((__funnelshift_l(c.x, c.x, 20) & 0x7FF800u) | eb0);
                    const float r3 = __uint_as_float((__funnelshift_l(c.y, c.y, 19) & 0x7F8000u) | eb0);
                    const float w = fmaf(s3, r3, fmaf(s2, r2, fmaf(s1, r1, fmaf(nw_hb, eb_f, r0))));
                    const float radial_dt = fmaf(ds3, r3, fmaf(ds2, r2, fmaf(ndt_hb, eb_f, r1)));  // 2^8 x d(w)/dt
                    const float q0 = Q3.y;
                    const float q1 = Q4.x;
                    const float q2 = Q4.w;
                    const float q3 = Q5.z;
                    const float q4 = Q6.y;
                    const float qzz = -q0 - q3;
                    const float vx = q0 * nx + q1 * ny + q2 * nz, vy = q1 * nx + q3 * ny + q4 * nz, vz = q2 * nx + q4 * ny + qzz * nz;
                    const float h = nx * vx + ny * vy + nz * vz;
                    const float A = xx * nx + xy * ny + xz * nz;
                    const float B2 = xx * vx + xy * vy + xz * vz;
                    pull_R = fmaf(radial_dt, A * h - 0.4f * B2, pull_R);
                    const float wh = w * h, wA2 = 2.0f * w * A, wk2 = 0.4f * w;
                    pull_Gx = fmaf(wh, xx, fmaf(wA2, vx, fmaf(-wk2, q0 * xx + q1 * xy + q2 * xz, pull_Gx)));
                    pull_Gy = fmaf(wh, xy, fmaf(wA2, vy, fmaf(-wk2, q1 * xx + q3 * xy + q4 * xz, pull_Gy)));
                    pull_Gz = fmaf(wh, xz, fmaf(wA2, vz, fmaf(-wk2, q2 * xx + q4 * xy + qzz * xz, pull_Gz)));
                    dx1x_acc = fmaf(wh, nx, fmaf(-wk2, vx, dx1x_acc));
                    dx1y_acc = fmaf(wh, ny, fmaf(-wk2, vy, dx1y_acc));
                    dx1z_acc = fmaf(wh, nz, fmaf(-wk2, vz, dx1z_acc));
                }
            const float4 Q7 = sq4[7];
            const float4 Q8 = sq4[8];
            const float4 Q9 = sq4[9];
                { // path 8 (0, 3, 3) scalar
                    const uint2 c = __ldg(slab_ptr + 1024 + channel);
                    const unsigned eb0 = (c.y & 0x0F800000u) + bias_shift;
                    const float eb_f = __uint_as_float(eb0);
                    const float r0 = __uint_as_float((c.x & 0x7FFFF8u) | eb0);
                    const float r1 = __uint_as_float((c.y & 0x7FFFF0u) | eb0);
                    const float r2 = __uint_as_float((__funnelshift_l(c.x, c.x, 20) & 0x7FF800u) | eb0);
                    const float r3 = __uint_as_float((__funnelshift_l(c.y, c.y, 19) & 0x7F8000u) | eb0);
                    const float w = fmaf(s3, r3, fmaf(s2, r2, fmaf(s1, r1, fmaf(nw_hb, eb_f, r0))));
                    const float radial_dt = fmaf(ds3, r3, fmaf(ds2, r2, fmaf(ndt_hb, eb_f, r1)));  // 2^8 x d(w)/dt
                    const float q0 = Q6.z;
                    const float q1 = Q7.x;
                    const float q2 = Q7.z;
                    const float q3 = Q8.x;
                    const float q4 = Q8.z;
                    const float q5 = Q9.x;
                    const float q6 = Q9.z;
                    const float q7 = -q0 - q3, q8 = -q1 - q5;
                    const float Qxx = q0 * nx + q1 * ny + q2 * nz, Qxy = q1 * nx + q3 * ny + q4 * nz, Qxz = q2 * nx + q4 * ny + q7 * nz;
                    const float Qyy = q3 * nx + q5 * ny + q6 * nz, Qyz = q4 * nx + q6 * ny + q8 * nz, Qzz = -Qxx - Qyy;
                    const float vx = Qxx * nx + Qxy * ny + Qxz * nz, vy = Qxy * nx + Qyy * ny + Qyz * nz, vz = Qxz * nx + Qyz * ny + Qzz * nz;
                    const float h = nx * vx + ny * vy + nz * vz;
                    const float wx = 3.0f * w * x0_v;
                    pull_Gx = fmaf(wx, vx, pull_Gx);
                    pull_Gy = fmaf(wx, vy, pull_Gy);
                    pull_Gz = fmaf(wx, vz, pull_Gz);
                    dx0_acc = fmaf(w, h, dx0_acc);
                    pull_R = fmaf(radial_dt, x0_v * h, pull_R);
                }
                { // path 9 (1, 2, 3) raise
                    const uint2 c = __ldg(slab_ptr + 1152 + channel);
                    const unsigned eb0 = (c.y & 0x0F800000u) + bias_shift;
                    const float eb_f = __uint_as_float(eb0);
                    const float r0 = __uint_as_float((c.x & 0x7FFFF8u) | eb0);
                    const float r1 = __uint_as_float((c.y & 0x7FFFF0u) | eb0);
                    const float r2 = __uint_as_float((__funnelshift_l(c.x, c.x, 20) & 0x7FF800u) | eb0);
                    const float r3 = __uint_as_float((__funnelshift_l(c.y, c.y, 19) & 0x7F8000u) | eb0);
                    const float w = fmaf(s3, r3, fmaf(s2, r2, fmaf(s1, r1, fmaf(nw_hb, eb_f, r0))));
                    const float radial_dt = fmaf(ds3, r3, fmaf(ds2, r2, fmaf(ndt_hb, eb_f, r1)));  // 2^8 x d(w)/dt
                    const float q0 = Q6.w;
                    const float q1 = Q7.y;
                    const float q2 = Q7.w;
                    const float q3 = Q8.y;
                    const float q4 = Q8.w;
                    const float q5 = Q9.y;
                    const float q6 = Q9.w;
                    const float q7 = -q0 - q3, q8 = -q1 - q5;
                    const float Qxx = q0 * nx + q1 * ny + q2 * nz, Qxy = q1 * nx + q3 * ny + q4 * nz, Qxz = q2 * nx + q4 * ny + q7 * nz;
                    const float Qyy = q3 * nx + q5 * ny + q6 * nz, Qyz = q4 * nx + q6 * ny + q8 * nz, Qzz = -Qxx - Qyy;
                    const float vx = Qxx * nx + Qxy * ny + Qxz * nz, vy = Qxy * nx + Qyy * ny + Qyz * nz, vz = Qxz * nx + Qyz * ny + Qzz * nz;
                    const float h = nx * vx + ny * vy + nz * vz;
                    pull_R = fmaf(radial_dt, 3.0f * (xx * vx + xy * vy + xz * vz), pull_R);
                    const float w3 = 3.0f * w, w6 = 6.0f * w;
                    dx1x_acc = fmaf(w3, vx, dx1x_acc);
                    dx1y_acc = fmaf(w3, vy, dx1y_acc);
                    dx1z_acc = fmaf(w3, vz, dx1z_acc);
                    pull_Gx = fmaf(w6, Qxx * xx + Qxy * xy + Qxz * xz, pull_Gx);
                    pull_Gy = fmaf(w6, Qxy * xx + Qyy * xy + Qyz * xz, pull_Gy);
                    pull_Gz = fmaf(w6, Qxz * xx + Qyz * xy + Qzz * xz, pull_Gz);
                }
            atomicAdd(dx0 + (int64_t)snd * C + channel, dx0_acc);
            atomicAdd(dx1 + ((int64_t)snd * 3 + 0) * C + channel, dx1x_acc);
            atomicAdd(dx1 + ((int64_t)snd * 3 + 1) * C + channel, dx1y_acc);
            atomicAdd(dx1 + ((int64_t)snd * 3 + 2) * C + channel, dx1z_acc);
        }

        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            pull_Gx += __shfl_xor_sync(0xffffffffu, pull_Gx, off, 32);
            pull_Gy += __shfl_xor_sync(0xffffffffu, pull_Gy, off, 32);
            pull_Gz += __shfl_xor_sync(0xffffffffu, pull_Gz, off, 32);
            pull_R  += __shfl_xor_sync(0xffffffffu, pull_R,  off, 32);
        }
        if (lane == 0) {
            const float sx_raw = tsx.y;
            float rad = 0.0f;
            if (sx_raw > 0.0f) {
                const float4 dc = __ldg(density_table + slab);
                const float ddens = (dc.y + t * (2.0f * dc.z + 3.0f * t * dc.w)) * sx_raw;
                rad = pull_R * 0x1.0p-8f * sx_raw + dD1_r * ddens;
            }
            const float gdotn = pull_Gx * nx + pull_Gy * ny + pull_Gz * nz;
            edge_force_1[e * 3 + 0] = nx * rad + (pull_Gx - nx * gdotn) * inv_r;
            edge_force_1[e * 3 + 1] = ny * rad + (pull_Gy - ny * gdotn) * inv_r;
            edge_force_1[e * 3 + 2] = nz * rad + (pull_Gz - nz * gdotn) * inv_r;
        }
    }
}
